package com.poi.investment.bond;
import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="bonds") public class Bond {@Id @Column(length=32)private String isin;@Column(nullable=false)private String issuer;private BigDecimal couponRate;private BigDecimal marketPrice;private String rating;protected Bond(){}public Bond(String isin,String issuer,BigDecimal couponRate,BigDecimal marketPrice,String rating){this.isin=isin;update(issuer,couponRate,marketPrice,rating);}public void update(String issuer,BigDecimal couponRate,BigDecimal marketPrice,String rating){this.issuer=issuer;this.couponRate=couponRate;this.marketPrice=marketPrice;this.rating=rating;}public String getIsin(){return isin;}public String getIssuer(){return issuer;}public BigDecimal getCouponRate(){return couponRate;}public BigDecimal getMarketPrice(){return marketPrice;}public String getRating(){return rating;}}
